  ('12690113-43e0-5570-9d59-d912152458ae', 'adams-river', 'Adams River', 'park', st_setsrid(st_makepoint(-119.7, 50.98), 4326)::geography, 'CA', 'America/Vancouver', null, null, 'Dominant-year sockeye turn the river red in October.', 'published'),
  ('3cfc91bc-bbf8-5599-8c47-d3ba918b1319', 'hervey-bay', 'Hervey Bay', 'city', st_setsrid(st_makepoint(152.85, -25.29), 4326)::geography, 'AU', 'Australia/Brisbane', null, null, 'Humpbacks rest in the lee of Fraser Island on the northbound run.', 'published'),
  ('78ffd720-7858-576e-a744-0e7771f929b2', 'onion-portage', 'Onion Portage, Kobuk Valley', 'park', st_setsrid(st_makepoint(-158.27, 67.11), 4326)::geography, 'US', 'America/Anchorage', null, null, 'A river pinch-point on the Western Arctic caribou herd''s autumn walk.', 'published'),
  ('c736c3e6-d098-5ac2-b8b3-c35fdf1b49eb', 'kasanka', 'Kasanka National Park', 'park', st_setsrid(st_makepoint(30.25, -12.58), 4326)::geography, 'ZM', 'Africa/Lusaka', null, null, 'Ten million straw-coloured fruit bats in a few hectares of mushitu swamp forest.', 'published'),
  ('477cc824-1962-5a12-b843-4491fc8e4265', 'nxai-pan', 'Nxai Pan', 'park', st_setsrid(st_makepoint(24.77, -19.93), 4326)::geography, 'BW', 'Africa/Gaborone', null, null, 'Zebra front arriving with the first rains on the Boteti–Nxai route.', 'published'),
  ('60790252-9fe8-5f79-ad19-8affe5dcac48', 'slaughter-beach', 'Slaughter Beach', 'point', st_setsrid(st_makepoint(-75.3, 38.91), 4326)::geography, 'US', 'America/New_York', null, null, 'Delaware Bay — horseshoe crabs and the red knots that time their flight to the spawn.', 'published'),
  ('9c56033f-5b74-5243-a65e-768f64411fce', 'rome', 'Rome', 'city', st_setsrid(st_makepoint(12.4964, 41.9028), 4326)::geography, 'IT', 'Europe/Rome', null, 'd0335318-9f4b-51d5-95dc-099303a18c40', 'Default origin for an Italy fortnight — rail in every direction.', 'published'),
  ('89d60bf7-9989-575d-a8f2-b114770bc5da', 'florence', 'Florence', 'city', st_setsrid(st_makepoint(11.2558, 43.7696), 4326)::geography, 'IT', 'Europe/Rome', null, 'd0335318-9f4b-51d5-95dc-099303a18c40', 'Gateway to Chianti harvest and the Impruneta grape festival.', 'published'),
  ('29c04436-bc3b-5e5b-9b32-541a241bcee4', 'venice', 'Venice', 'city', st_setsrid(st_makepoint(12.3155, 45.4408), 4326)::geography, 'IT', 'Europe/Rome', null, 'd0335318-9f4b-51d5-95dc-099303a18c40', 'Lagoon city — closest big station to the Po Delta passage.', 'published'),
  ('fcd72d9e-adf9-5004-9557-af888018ee8e', 'chianti', 'Chianti', 'region', st_setsrid(st_makepoint(11.3, 43.47), 4326)::geography, 'IT', 'Europe/Rome', null, 'd0335318-9f4b-51d5-95dc-099303a18c40', 'Sangiovese hills between Florence and Siena.', 'published'),
  ('d546b1e7-6108-5adb-988e-259f3f71c030', 'alba-langhe', 'Alba & the Langhe', 'region', st_setsrid(st_makepoint(8.04, 44.7), 4326)::geography, 'IT', 'Europe/Rome', null, 'd0335318-9f4b-51d5-95dc-099303a18c40', 'Nebbiolo harvest and the white-truffle capital.', 'published'),
  ('a32e2885-3a48-5022-83e1-7e3785c5aa65', 'po-delta', 'Po Delta', 'park', st_setsrid(st_makepoint(12.2, 44.68), 4326)::geography, 'IT', 'Europe/Rome', null, 'd0335318-9f4b-51d5-95dc-099303a18c40', 'Ramsar wetlands on the Adriatic — autumn waterfowl highway.', 'published'),
  ('dc2cd10b-b85a-5fd9-b681-01f1136dd262', 'val-di-funes', 'Val di Funes', 'region', st_setsrid(st_makepoint(11.68, 46.64), 4326)::geography, 'IT', 'Europe/Rome', 1600, 'd0335318-9f4b-51d5-95dc-099303a18c40', 'Odle peaks above a valley of larch that turns gold in October.', 'published'),
  ('56ea7318-5e81-5e34-9b48-db78cd06da64', 'cinque-terre', 'Cinque Terre', 'region', st_setsrid(st_makepoint(9.71, 44.13), 4326)::geography, 'IT', 'Europe/Rome', null, 'd0335318-9f4b-51d5-95dc-099303a18c40', 'Cliff vineyards still picking into late September.', 'published'),
  ('74300c63-5b65-57e5-a5e6-8e2b82340334', 'umbria-norcia', 'Norcia & the Sibillini', 'region', st_setsrid(st_makepoint(12.89, 42.79), 4326)::geography, 'IT', 'Europe/Rome', null, 'd0335318-9f4b-51d5-95dc-099303a18c40', 'Apennine woods — porcini, sagre, and Saturday village tables.', 'published'),
  ('03212e23-39a0-58a0-a737-07b7cff1e893', 'mount-etna', 'Mount Etna', 'park', st_setsrid(st_makepoint(14.99, 37.75), 4326)::geography, 'IT', 'Europe/Rome', 3320, 'd0335318-9f4b-51d5-95dc-099303a18c40', 'Summit season holds through October when the scirocco stays kind.', 'published')
insert into phenomenon (id, slug, name, family, tags, summary, description_md, practical, spectacle, status, published_at) values
  ('94c9d8cf-6ef8-5e5b-8c85-c44dfe0a15c7', 'wildebeest-great-migration', 'Great Wildebeest Migration', 'wildlife', array['migration', 'safari', 'planet-earth']::text[], 'Two million animals follow the rains on an 1,800 km loop. River crossings peak in the Mara from late July.', 'The Serengeti–Mara circuit is not a single stampede. Calves drop on the southern plains in January and February. The columns walk north as the short rains fail, reach the Grumeti, then the Mara River. August and early September are when the crossings bunch — a week of quiet, then a morning when the lead animals commit.', '{"guideRecommended":true,"permit":"park fees","howToSee":"Base in the northern Serengeti or the Mara Triangle. Crossings are not scheduled; a good guide reads the river and the wind. Dawn and late afternoon. Stay at least three nights.","ethics":"Keep vehicles back from the banks. Do not block an animal that has committed to the water. No drones over crossings. The spectacle is the river deciding, not a staged charge."}'::jsonb, 5, 'published', now()),
  ('39c62b62-e4ae-541d-8ea4-2073bf60ceed', 'monarch-overwintering-michoacan', 'Monarch Overwintering', 'wildlife', array['migration', 'butterflies', 'planet-earth']::text[], 'Eastern monarchs carpet oyamel firs in Michoacán from November through March.', 'Four generations fly north; one generation flies south. By mid-November the colonies have coalesced on a handful of high fir forests west of Mexico City. On a warm midday they lift in sheets. On a cold morning they hang like rusted leaves.', '{"permit":"sanctuary ticket","howToSee":"El Rosario and Sierra Chincua are the public sanctuaries. Ride or walk the last kilometres. Mid-morning after the sun hits the groves. Weekdays are quieter.","ethics":"Stay on marked trails. Do not touch clusters. The fir understory is the wintering habitat — keep voices low and groups small."}'::jsonb, 5, 'published', now()),
  ('7e589234-4cbd-5098-8739-ae568e76e65f', 'gray-whale-baja-lagoons', 'Gray Whale Lagoons', 'wildlife', array['migration', 'whales', 'planet-earth']::text[], 'Mothers and calves in the Baja nursery lagoons, curious enough to approach a skiff.', 'Gray whales swim from the Bering and Chukchi to three Pacific lagoons. San Ignacio remains the quietest. February and March are when calves are large enough to spyhop beside boats, and when the last northbound adults still linger.', '{"needsBoat":true,"guideRecommended":true,"howToSee":"Pangas from the cooperativos only. Half-day on the water. Bring a wind layer — the lagoon fetches.","ethics":"Engines idle near whales. No swimming. Mothers choose the approach; if she turns away, the boat does too."}'::jsonb, 5, 'published', now()),
  ('422c615e-dcc1-5a8f-b63a-9bdd1bce66a8', 'sardine-run-wild-coast', 'Sardine Run', 'wildlife', array['migration', 'ocean', 'planet-earth']::text[], 'A cold current herds sardines up the Wild Coast — sharks, gannets and dolphins in one bait-ball.', 'The run is a pulse, not a parade. Water temperature, wind and the sardines themselves have to agree. June and July are the window; some years the action sits offshore, some years it boils in the first break.', '{"needsBoat":true,"guideRecommended":true,"howToSee":"Port St Johns and Coffee Bay are the usual launch points. Dive or snorkel boats work the bait-balls. Budget extra days — the ocean cancels.","ethics":"Do not break a bait-ball for a photograph. Give gannets and sharks the column. If you are not a strong ocean swimmer, watch from the cliffs."}'::jsonb, 5, 'published', now()),
  ('c1d7c623-62f1-5da4-960d-e9324feca82b', 'christmas-island-red-crabs', 'Christmas Island Red Crabs', 'wildlife', array['migration', 'planet-earth']::text[], 'Tens of millions of red crabs walk to the sea on the first heavy rains of the wet season.', 'The migration is timed to the moon and the rain. Crabs leave the forest, close the island''s roads, release larvae on the turning tide, then walk home. Parks Australia publishes a watch when the first storms arrive.', '{"howToSee":"Late October into November in a typical wet start. Drive slowly; the crabs have right of way. Dawn on the terrace forests.","ethics":"Never move a crab except off a wheel track. Lights and noise on the beaches during spawning are the usual harm."}'::jsonb, 5, 'published', now()),
  ('e1aa949f-627b-54bb-b4d9-499b457af0fe', 'sandhill-crane-platte-river', 'Sandhill Cranes on the Platte', 'wildlife', array['migration', 'birds', 'planet-earth']::text[], 'Half a million cranes roost on a few miles of braided river in March.', 'The Central Flyway pinches at the Platte. From late February the birds stack on sandbars, then fan into corn stubble at dawn. Late March is peak density — a sound first, then a sky.', '{"howToSee":"Rowe Sanctuary blinds at dawn and dusk. Book the blinds; roadside pull-offs work if you keep the car as a hide.","ethics":"Stay in blinds after last light. Flash and silhouettes flush the river. Give farmers'' fields the same courtesy."}'::jsonb, 5, 'published', now()),
  ('fc6f73d9-e05c-5e97-99a0-ceb031d12194', 'sockeye-salmon-adams-river', 'Adams River Sockeye', 'wildlife', array['migration', 'salmon', 'planet-earth']::text[], 'A dominant-year run turns the Adams crimson in October.', 'Sockeye return on a four-year drum. 2026 is a strong cycle year: the river fills from early October, peak colour in the second and third weeks. The Salish name and the science agree — this is a pulse, then it is gone.', '{"howToSee":"Roderick Haig-Brown Park boardwalks. Mid-morning light on the riffles. Waterproof shoes; the banks are clay.","ethics":"Stay off redds. No wading through spawning pairs. Bears work these banks — give them the water."}'::jsonb, 4, 'published', now()),
  ('deb9ede1-6523-532e-af2f-4e7d7976c145', 'humpback-whales-hervey-bay', 'Humpbacks in Hervey Bay', 'wildlife', array['migration', 'whales', 'planet-earth']::text[], 'Northbound humpbacks rest in the lee of K''gari from late July through September.', 'The bay is a classroom. Mothers teach calves in flat water. August is crowded with boats and with whales; September thins and the animals linger.', '{"needsBoat":true,"guideRecommended":true,"howToSee":"Licensed vessels from Urangan. Half-day is enough if the wind stays under 15 knots.","ethics":"Approach distances are enforced. Swim-with is a separate, tightly licensed product — do not freelance it."}'::jsonb, 4, 'published', now()),
  ('0257f6ab-ff3c-56c6-8033-7ba46d6de969', 'western-arctic-caribou-crossing', 'Western Arctic Caribou', 'wildlife', array['migration', 'planet-earth']::text[], 'The herd pinches through Onion Portage on the autumn walk toward the Kobuk.', 'This is not a guaranteed spectacle. The Western Arctic herd chooses drainages. When they use Onion Portage, the river fills with antlers for a few days in early September.', '{"howToSee":"Charter to Kobuk Valley. The park service posts crossing notes. Weather cancels more days than it allows.","ethics":"This is Iñupiaq hunting country. Give camps and hunters the bank. No low flights over a crossing column."}'::jsonb, 4, 'published', now()),
  ('5c5bd70f-163e-5ca0-950f-507717f05ba0', 'straw-coloured-fruit-bats-kasanka', 'Kasanka Fruit Bats', 'wildlife', array['migration', 'planet-earth']::text[], 'The largest mammal migration on the continent — by headcount — fills a few hectares of swamp forest.', 'From late October the mushitu canopy blackens. At dusk the column lifts for forty minutes. Peak density is mid-November. By Christmas the trees are ordinary again.', '{"howToSee":"Fibwe hide at last light. Stay two nights. The park is small; the hide is the product.","ethics":"No lights into the roost. The forest floor is a latrine and a nursery — stay on the boardwalk."}'::jsonb, 5, 'published', now()),
  ('8065f2e0-c3e8-5068-8d50-e1dace700932', 'zebra-migration-nxai-pan', 'Nxai Pan Zebra Front', 'wildlife', array['migration', 'planet-earth']::text[], 'Zebras arrive with the first rains on the Boteti–Nxai route, December into February.', 'Less filmed than the Mara, more of a weather bet. When the pans hold water the zebra front is a dark tide on white calcrete.', '{"howToSee":"Nxai Pan camp after the first proper storm. December is early; January is the safer bet.","ethics":"Off-road driving scars the pans for years. Stay in tracks."}'::jsonb, 4, 'published', now()),
  ('91544d31-ccca-5cfd-9ae8-d230c9c019d9', 'horseshoe-crabs-red-knots-delaware', 'Horseshoe Crabs & Red Knots', 'wildlife', array['migration', 'planet-earth']::text[], 'A full-moon spawn on Delaware Bay feeds birds that have flown from Tierra del Fuego.', 'The crabs come up on the spring tides of late May. Red knots time a 15,000 km flight to those eggs. Two weeks, then the beach is ordinary sand again.', '{"howToSee":"Slaughter Beach and Mispillion Harbor at night on the highest tides. Bring a dim red light.","ethics":"Stay off the wrack line. The knots are exhausted; a flushed flock can miss a feeding window."}'::jsonb, 4, 'published', now()),
  ('c01ebbc8-1f3f-5b8a-9879-44443825c596', 'vendemmia-chianti', 'Chianti Vendemmia', 'activity', array['harvest', 'wine', 'italy']::text[], 'Sangiovese comes in from late August through early October. Mid-September is the crush.', 'The vendemmia is work that looks like a festival from the road. Tractors in the rows, purple hands, the smell of must in every village. 2026 is running a few days early on the lower slopes.', '{"howToSee":"Book a morning pick-and-lunch with a small estate south of Greve or Panzano. Afternoons are for the cellars.","ethics":"Vineyards are workplaces. Do not walk rows uninvited. Spit or sip — don''t treat a working crush as a tasting room."}'::jsonb, 4, 'published', now()),
  ('4a968156-8217-5656-8fd3-e174513f58eb', 'vendemmia-nebbiolo-langhe', 'Nebbiolo Harvest, Langhe', 'activity', array['harvest', 'wine', 'italy']::text[], 'Nebbiolo hangs longer than sangiovese. The Langhe crush starts in the last days of September.', 'Barolo and Barbaresco villages empty into the rows. Fog in the morning, gold in the afternoon. The first week of October is when the best-exposed slopes come in.', '{"howToSee":"Alba or La Morra as a base. Estates take guests by appointment during harvest week.","ethics":null}'::jsonb, 4, 'published', now()),
  ('a38f954f-caf2-5372-ab3d-6fe0ec077982', 'white-truffle-piedmont', 'White Truffle Season', 'activity', array['harvest', 'food', 'italy']::text[], 'Tuber magnatum arrives with the first cool nights. The season opens in late September; it peaks later.', 'Trifolaio and dog work the oak and linden woods after rain. The official season is long. The aromatic peak is usually mid-October through November. In the last ten days of September you are tasting the opening, not the climax.', '{"howToSee":"Alba market mornings. A trifolaio walk is the honest version; a restaurant shaving is the easy one.","ethics":"Wild truffles are a regulated harvest. Do not follow a dog into private woods."}'::jsonb, 4, 'published', now()),
  ('126860ef-e702-5c35-9a6c-6d4331ed3f17', 'alba-truffle-fair', 'Alba White Truffle Fair', 'cultural', array['festival', 'food', 'italy']::text[], 'The international fair fills Alba''s weekends from mid-October.', 'Cortile della Maddalena becomes a covered market of graded tartufi, cheese and Barolo. Saturdays and Sundays, mid-October to early December.', '{"howToSee":"Arrive Saturday morning before the tour buses. The judging tables are the education.","ethics":null}'::jsonb, 3, 'published', now()),
  ('91ef2a9b-3cc0-5fe0-9a09-98d626f52e8a', 'dolomites-larch-turn', 'Dolomites Larch Turn', 'seasonal_nature', array['foliage', 'italy']::text[], 'European larch goes from green to coin-gold above Val di Funes in early October.', 'Larch is a deciduous conifer. The colour is a week, maybe two, and it starts at elevation. Late September is the first hint; the second week of October is the postcard — if a storm has not stripped the needles.', '{"howToSee":"Santa Maddalena meadows at 9 a.m. when the Odle still hold shadow. The Santa Croce walk is the high version.","ethics":null}'::jsonb, 4, 'published', now()),
  ('3ea2c7b5-a6d7-514e-a3c6-5d123d20a012', 'sagre-umbria-autumn', 'Umbrian Autumn Sagre', 'cultural', array['festival', 'food', 'italy']::text[], 'Village food festivals every weekend from September into November — wild boar, chestnuts, norcineria.', 'A sagra is a town feeding itself in public. Long tables, paper cups, a saint or a harvest as the excuse. Umbria does this better than almost anywhere in the peninsula.', '{"howToSee":"Pick a Saturday. Norcia, Spello, Bevagna and the mountain villages rotate. Eat what the handwritten menu says.","ethics":null}'::jsonb, 3, 'published', now()),
  ('ceed379f-36b0-5b51-b7d9-f275208e4d17', 'po-delta-autumn-passage', 'Po Delta Autumn Passage', 'wildlife', array['birds', 'migration', 'italy']::text[], 'Waterfowl and waders stack in the delta from mid-September. Spoonbill, flamingo, and the first geese.', 'The Adriatic flyway pinches at the Po mouths. Mid-September to mid-October is the busy fortnight — not a single species spectacle, a density of wings.', '{"howToSee":"Boat from Porto Tolle or hides at the Bertuzzi valleys. Dawn. Bring a scope if you have one.","ethics":"Stay in hides and marked boats. The delta is a working fishery as well as a park."}'::jsonb, 3, 'published', now()),
  ('c96ee6b3-1d57-5b23-946b-42c0c5726aa4', 'festa-delluva-impruneta', 'Festa dell''Uva, Impruneta', 'cultural', array['festival', 'wine', 'italy']::text[], 'Impruneta''s grape festival fills a Sunday at the end of September — floats, chianti, the whole hill in the piazza.', 'Four contrade build allegorical floats from flowers and grapes. The parade is the afternoon; the evening is the town drinking its own vintage.', '{"howToSee":"Bus or taxi from Florence (40 minutes). Arrive before 14:00 for a place on the route.","ethics":null}'::jsonb, 3, 'published', now()),
  ('8e6ff7a7-0ff6-5f45-8f7e-504d18bafa3b', 'porcini-apennines', 'Porcini in the Apennines', 'seasonal_nature', array['forage', 'italy']::text[], 'Boletus after the first autumn rains. A week of plenty, then the woods go quiet.', 'Porcini are a weather instrument. Warm days, cool nights, a soaking rain. Late September 2026 has the pattern. The woods above Norcia and the Casentino are the usual bet.', '{"howToSee":"Go with someone who has a local permit and a knife. Markets in Norcia tell you if the week is real.","ethics":"Permits, quotas, and no rakes. Leave the buttons; take the open caps."}'::jsonb, 3, 'published', now()),
  ('e45726e2-d691-5375-9282-de63b2b54a17', 'etna-summit-season', 'Etna Summit Season', 'activity', array['volcano', 'italy']::text[], 'Guided high routes stay open through October. September light is the reason to go.', 'The mountain makes its own weather. Summer crowds thin after Ferragosto. September and early October are when the scirocco is less constant and the lava fields hold the day''s heat.', '{"guideRecommended":true,"permit":"authorised guide above 2500 m","howToSee":"Cable car plus authorised guide above 2,500 m. Check the day''s bulletin — closures are ordinary.","ethics":"Stay on marked high routes. The new lava is a crust, not a path."}'::jsonb, 4, 'published', now()),
  ('aa52c337-9e8a-5516-b539-6e4ebfd22e79', 'olive-harvest-tuscany', 'Tuscan Olive Harvest', 'activity', array['harvest', 'italy']::text[], 'Nets go down in late October. The new oil — olio nuovo — is a November taste.', 'Olives hang after the grapes. Mid-October is early on most Chianti slopes; November is the crush. If you are here in the last week of September you are smelling the vineyards, not the frantoi.', '{"howToSee":"A frantoio visit in November. In late September, walk the groves and book the later week.","ethics":null}'::jsonb, 3, 'published', now()),
  ('1b088392-dd1d-5fdd-88ee-2d020e691e12', 'september-equinox', 'September Equinox', 'astronomy', array['sky', 'equinox']::text[], 'Equal day and night — the astronomical start of autumn in the north.', 'The Sun crosses the celestial equator heading south. In Italy that is a late-September evening in civil time. Not a spectacle in the sky so much as a hinge in the year: harvest light, earlier dark, the first excuse for a jacket.', '{"howToSee":"Sunset from any west-facing hill. The event is a clock, not a glow.","ethics":null}'::jsonb, 3, 'published', now()),
  ('8f0da94a-cba0-5b48-84e6-cfbb0a9ac76f', 'harvest-full-moon', 'Harvest Full Moon', 'astronomy', array['sky', 'moon']::text[], 'The full moon nearest the September equinox — low, large, and useful to anyone still in the rows.', 'Farmers named it because it rises close to sunset and stays useful. In 2026 it falls on 26 September. From a Tuscan ridge it clears the vines while the west is still salmon.', '{"needsDarkSky":false,"howToSee":"Any open eastern horizon. City centres wash it out; Fiesole or Chianti do not.","ethics":null}'::jsonb, 3, 'published', now())
